1	type Customer = { yearsWithMHPCO: number };
2	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
3	type Step = { op: "quote"; items: Item[] };
4	type Scenario = { customer: Customer; steps: Step[] };
5	
6	type QuoteResult = { premium: number };
7	type ScenarioResult = { results: QuoteResult[] };
8	
9	const PROCESSING_FEE = 5;
10	const FIRST_INSURANCE_PCT = 0.10;
11	const LOYALTY_PCT = 0.20;
12	const LOYALTY_YEARS = 2;
13	const CURSE_PCT = 0.50;
14	const HIGH_ENCH_PCT = 0.30;
15	const HIGH_ENCH_THRESHOLD = 5;
16	const FLOAT_TOLERANCE = 1e-9;
17	const BLOCK_SIZE = 3;
18	const BLOCK_PREMIUM = 60;
19	
20	const BASE_PREMIUM: Record<string, number> = {
21	  sword: 100,
22	  amulet: 60,
23	  staff: 80,
24	  potion: 40,
25	  rune: 25,
26	  moonstone: 25,
27	};
28	
29	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
30	
31	const isComponentType = (type: string): boolean => COMPONENT_TYPES.has(type);
32	
33	const roundUp = (n: number): number => Math.ceil(n - FLOAT_TOLERANCE);
34	
35	const countByType = (items: Item[]): Map<string, number> => {
36	  const counts = new Map<string, number>();
37	  for (const item of items) {
38	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
39	  }
40	  return counts;
41	};
42	
43	const groupBasePremium = (type: string, count: number): number =>
44	  isComponentType(type) && count === BLOCK_SIZE
45	    ? BLOCK_PREMIUM
46	    : count * BASE_PREMIUM[type];
47	
48	const sumBasePremiums = (items: Item[]): number => {
49	  let total = 0;
50	  for (const [type, count] of countByType(items)) {
51	    total += groupBasePremium(type, count);
52	  }
53	  return total;
54	};
55	
56	const isHighlyEnchanted = (item: Item): boolean =>
57	  (item.enchantment ?? 0) >= HIGH_ENCH_THRESHOLD;
58	
59	const itemSurchargePct = (item: Item): number =>
60	  (item.cursed ? CURSE_PCT : 0) +
61	  (isHighlyEnchanted(item) ? HIGH_ENCH_PCT : 0);
62	
63	const itemSurcharge = (item: Item): number =>
64	  BASE_PREMIUM[item.type] * itemSurchargePct(item);
65	
66	const itemSurcharges = (items: Item[]): number =>
67	  items.reduce((total, item) => total + itemSurcharge(item), 0);
68	
69	const policyDiscountPct = (customer: Customer): number =>
70	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_PCT : 0;
71	
72	const computeQuotePremium = (items: Item[], customer: Customer): number => {
73	  const policyBase = sumBasePremiums(items);
74	  const surcharges = itemSurcharges(items);
75	  const policyMods = FIRST_INSURANCE_PCT - policyDiscountPct(customer);
76	  return roundUp(policyBase + surcharges + policyBase * policyMods + PROCESSING_FEE);
77	};
78	
79	export const runScenario = (scenario: Scenario): ScenarioResult => ({
80	  results: scenario.steps.map((step) => ({ premium: computeQuotePremium(step.items, scenario.customer) })),
81	});
