const loyaltyDiscountPct = (customer: Customer): number =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_PCT : 0;

const policyBaseMultiplier = (customer: Customer): number =>
  1 + FIRST_INSURANCE_PCT - loyaltyDiscountPct(customer);

const computeQuotePremium = (items: Item[], customer: Customer): number => {
  const policyBase = sumBasePremiums(items);
  return roundUp(
    policyBase * policyBaseMultiplier(customer) + itemSurcharges(items) + PROCESSING_FEE,
  );
};
